 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    trunk_rows = [r for r, cols in by_row.items() if len(cols) >= 2]
    if not trunk_rows:
        return out
    # The row containing the aligned pair is the horizontal backbone.
    trunk = trunk_rows[0]
    cols = by_row[trunk]
    for c in range(min(cols), max(cols) + 1):
        if out[trunk][c] == 0:
            out[trunk][c] = 3
    # Join each remaining point to the backbone in its own column.
    for r, c in points:
        if r == trunk:
            continue
        for rr in range(min(r, trunk) + 1, max(r, trunk)):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
